namespace Puck.SdfVm;

/// <summary>The mesh irradiance probe record shared by the CPU tracer and views shader, generated by <see cref="SdfIsaHlsl"/>.
/// It holds a key, six sky halves, eighteen radiance halves, light visibility bits, the relocated origin, and an octahedral map of first-hit surface support.</summary>
public static class SdfMeshIrradianceProbe {
    /// <summary>The octahedral depth map's width and height, without duplicated border texels.</summary>
    public const int DepthSize = 12;
    /// <summary>The first surface word: FP16 ray distance and two signed octahedral normal bytes.
    /// A negative distance means a miss to that reach.</summary>
    public const int DepthWord = 19;
    /// <summary>The packed surface words followed by one FP16 normal-gradient curvature per texel.</summary>
    public const int DepthWords = (((3 * DepthSize) * DepthSize) / 2);
    /// <summary>The signed octahedral normal byte's scale; axis normals remain exact.</summary>
    public const float DepthNormalScale = 127f;
    /// <summary>The surface gap over which an angular tap closes, in metres, smaller than normal bias.</summary>
    public const float DepthSurfaceFade = 0.02f;
    /// <summary>The symmetric point/normal residual below which angular taps belong to one smooth surface patch.</summary>
    public const float DepthSurfaceJoinGap = (2f * DepthSurfaceFade);
    /// <summary>The volume's nested levels, finest first; each level's slots follow the finer level's in the table.</summary>
    public const int Levels = Puck.Shaders.SdfWorldPackage.MeshIrradianceLevelCount;
    /// <summary>The words one probe takes in the volume table.</summary>
    public const int ProbeWords = (DepthWord + DepthWords);
    /// <summary>Two words of FP16 offset XYZ and back-face share. Every directional read uses this relocated origin.</summary>
    public const int OffsetWord = 17;
    /// <summary>The least distance in metres between a probe and any surface.</summary>
    public const float Clearance = 0.1f;
    /// <summary>The first word of the traced light visibility bits, one bit per lights-table record.</summary>
    public const int LightsWord = 13;
    /// <summary>The number of light visibility words.</summary>
    public const int LightWords = 4;
    /// <summary>The flag a written probe carries.</summary>
    public const uint WrittenFlag = (1u << 30);
    /// <summary>The flag of a probe no candidate could move into the open.</summary>
    public const uint InvalidFlag = (1u << 31);
    /// <summary>The receiver's normal bias in metres, smaller than the thinnest wall, independent of probe spacing.</summary>
    public const float NormalBias = 0.05f;
    /// <summary>A probe's surface map reach in spacings, one and a half cell diagonals (1.5 √3): with
    /// <see cref="NormalBias"/> added, the farthest receiver in metres a probe measured, its surface map past that a miss.
    /// A level's probes answer receivers this far past its window's boundary probes before a coarser level does.</summary>
    public const float SurfaceReach = (1.5f * 1.7320508f);
    /// <summary>The facing weight a finest-level probe behind the receiver's plane keeps: small beside a probe in front, so
    /// it barely shifts a receiver that front probes light, and the whole answer for a receiver no front probe can see,
    /// such as a downward rim at the ground whose front probes the ground hides, which would otherwise draw black. A coarser
    /// level's probe behind the plane keeps none: its depth test cannot resolve the receiver's own wall.</summary>
    public const float BehindShare = 0.05f;
    /// <summary>The finest level's hit footprint share below which an edge tap cannot extend a finite block: a 1 m probe's
    /// taps are half a metre wide, and a tap half blocked by a railing must not shadow the floor beyond it.</summary>
    public const float DepthCoverageStart = 0.5f;
    /// <summary>Scales the finest level's closing ramp to complete at three-quarter coverage.</summary>
    public const float DepthCoverageScale = 4f;
    /// <summary>A coarser level's hit footprint share at which its closing ramp starts: none, since an 8 m probe's taps
    /// are metres wide and any hit they measured before the receiver is a slab or a wall between them.</summary>
    public const float CoarseDepthCoverageStart = 0f;
    /// <summary>Scales a coarser level's closing ramp to complete at an eighth of the footprint blocked.</summary>
    public const float CoarseDepthCoverageScale = 8f;
}
